/* eslint-disable @next/next/no-img-element */
"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { ArrowLeft, BarChart3, Bell, BookOpen, CalendarDays, ChevronDown, ChevronRight, ClipboardList, Download, History, Home, ImagePlus, Lightbulb, LogOut, Menu, Minus, Package, Pencil, Plus, Search, Settings, ShoppingBag, Star, Trash2, Users, WalletCards, X } from "lucide-react";
import { PRODUCTS, SERVICES } from "./constants";
import { deleteRecord, fetchRecords, hasAdminSession, insertRecord, isSupabaseConfigured, recordActivity, signOutAdmin, supabase, updateRecord, upsertRecord } from "./lib/supabase";
import { AdminLogin } from "./AdminLogin";
import { deleteLocalRecords, loadCatalog, loadRecords, patchLocalRecord, saveCatalog } from "./lib/gailand-store";
import { openPaystackPayment } from "./lib/paystack";
import { cleanupImages, uploadImage } from "./lib/cloudinary";

type View = "Overview" | "Bookings" | "Consultations" | "Orders" | "History" | "Services" | "Products" | "Point of Sale" | "Clients" | "Reviews" | "Insights" | "Staff" | "Settings";
type Row = Record<string, unknown>;
type CartLine = { key: string; id: string; kind: "product" | "service"; name: string; price: number; quantity: number; inventory?: number };
type Receipt = { reference: string; items: CartLine[]; total: number; date: string; payment: string; customer: string };

const views: Array<{ name: View; icon: typeof Home }> = [
  { name: "Overview", icon: Home }, { name: "Bookings", icon: CalendarDays }, { name: "Consultations", icon: ClipboardList },
  { name: "Orders", icon: Package }, { name: "History", icon: History }, { name: "Services", icon: BookOpen },
  { name: "Products", icon: ShoppingBag }, { name: "Point of Sale", icon: WalletCards }, { name: "Clients", icon: Users },
  { name: "Reviews", icon: Star }, { name: "Insights", icon: BarChart3 }, { name: "Staff", icon: Users }, { name: "Settings", icon: Settings },
];
const viewTable: Partial<Record<View, string>> = { Bookings: "bookings", Consultations: "consultation_requests", Orders: "orders", Services: "services", Products: "products", Clients: "customers", Reviews: "testimonials", Staff: "staff", Settings: "business_settings" };
const operationViews: View[] = ["Bookings", "Consultations", "Orders"];
const money = (value: unknown) => `GH₵ ${Number(value || 0).toLocaleString("en-GH", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const text = (value: unknown, fallback = "—") => value == null || value === "" ? fallback : String(value);
const dateText = (value: unknown) => value ? new Date(String(value)).toLocaleString("en-GH", { dateStyle: "medium", timeStyle: "short" }) : "—";
const slug = (value: string) => value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

function localSeed(table: string) {
  return loadRecords(table);
}

export function AdminDashboard() {
  const [authReady, setAuthReady] = useState(false);
  const [loggedIn, setLoggedIn] = useState(false);
  const [view, setView] = useState<View>("Overview");
  const [drawer, setDrawer] = useState(false);
  const [data, setData] = useState<Record<string, Row[]>>({});
  const [loading, setLoading] = useState(false);
  const [notice, setNotice] = useState("");
  const [collapsed, setCollapsed] = useState(false);

  useEffect(() => { hasAdminSession().then(active => { setLoggedIn(active || !isSupabaseConfigured); setAuthReady(true); }); }, []);
  const refresh = useCallback(async () => {
    setLoading(true);
    const tables = ["bookings", "consultation_requests", "orders", "services", "products", "customers", "testimonials", "staff", "business_settings", "activity_log"];
    const entries = await Promise.all(tables.map(async table => {
      const result = await fetchRecords(table);
      return [table, result.local || result.error ? localSeed(table) : (result.data || [])] as const;
    }));
    setData(Object.fromEntries(entries)); setLoading(false);
  }, []);
  useEffect(() => { if (!loggedIn) return; const timer = window.setTimeout(() => void refresh(), 0); return () => window.clearTimeout(timer); }, [loggedIn, refresh]);
  useEffect(() => {
    if (!loggedIn || !supabase) return;
    const client = supabase;
    let timer: number | undefined;
    const channel = client.channel("admin-studio-live").on("postgres_changes", { event: "*", schema: "public" }, () => {
      window.clearTimeout(timer);
      timer = window.setTimeout(() => void refresh(), 180);
    }).subscribe();
    return () => { window.clearTimeout(timer); void client.removeChannel(channel); };
  }, [loggedIn, refresh]);

  if (!authReady) return <div className="adm-loading">Preparing your workspace…</div>;
  if (!loggedIn) return <AdminLogin onSuccess={() => setLoggedIn(true)} />;
  const flash = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(""), 3500); };
  const navigate = (next: View) => { setView(next); setDrawer(false); };

  return <div className={collapsed ? "adm-shell collapsed" : "adm-shell"}>
    <aside className={drawer ? "adm-sidebar open" : "adm-sidebar"}>
      <div className="adm-brand"><span>G</span><div><strong>Gailant Beauty</strong><small>ADMIN STUDIO</small></div><button type="button" className="adm-sidebar-toggle" onClick={() => setCollapsed(c => !c)} aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}><Menu /></button><button className="adm-mobile-close" onClick={() => setDrawer(false)} aria-label="Close menu"><X /></button></div>
      <nav>{[["", ["Overview"]], ["OPERATIONS", ["Bookings", "Consultations", "Orders", "Point of Sale"]], ["CATALOG", ["Products", "Services"]], ["CUSTOMERS", ["Clients", "Reviews"]], ["BUSINESS", ["Insights", "History", "Staff"]], ["", ["Settings"]]].map(([label, names], groupIndex) => <section key={groupIndex}>{label && <p>{label as string}</p>}{(names as string[]).map(name => { const item = views.find(entry => entry.name === name as View)!; const Icon = item.icon; return <button key={item.name} className={view === item.name ? "active" : ""} onClick={() => navigate(item.name)} title={collapsed ? item.name : undefined}><Icon /><span>{item.name}</span></button>; })}</section>)}</nav>
      <div className="adm-sidebar-foot"><a href="https://ayaaba.netlify.app" target="_blank" rel="noreferrer">Built by Ayaaba</a><button onClick={async () => { await signOutAdmin(); setLoggedIn(false); }}><LogOut /> <span>Sign out</span></button></div>
    </aside>
    {drawer && <button className="adm-scrim" onClick={() => setDrawer(false)} aria-label="Close navigation" />}
    <main className="adm-main">
      <AdminHeader view={view} loading={loading} activities={data.activity_log || []} navigate={navigate} />
      {notice && <div className="adm-notice" role="status">{notice}</div>}
      {loading && <div className="adm-page-skeleton" aria-label="Loading dashboard data"><i /><i /><i /><i /><i /></div>}
      {view === "Overview" && <Overview data={data} navigate={navigate} />}
      {view === "Bookings" && <ScheduleView rows={data.bookings || []} refresh={refresh} flash={flash} />}
      {operationViews.includes(view) && view !== "Bookings" && <Operations view={view} rows={data[viewTable[view]!] || []} refresh={refresh} flash={flash} />}
      {view === "History" && <HistoryView data={data} />}
      {(["Services", "Products", "Reviews", "Staff"] as View[]).includes(view) && <DataView view={view} rows={data[viewTable[view]!] || []} refresh={refresh} flash={flash} />}
      {view === "Clients" && <ClientsView rows={data.customers || []} orders={data.orders || []} bookings={data.bookings || []} refresh={refresh} flash={flash} />}
      {view === "Point of Sale" && <PointOfSale products={data.products || []} services={data.services || []} refresh={refresh} flash={flash} />}
      {view === "Insights" && <Insights data={data} />}
      {view === "Settings" && <SettingsView rows={data.business_settings || []} refresh={refresh} flash={flash} />}
      <footer className="adm-footer"><span>Gailant Beauty operations</span><a href="https://ayaaba.netlify.app" target="_blank" rel="noreferrer">Built by Ayaaba</a></footer>
    </main>
    <nav className="adm-bottom-nav">{views.slice(0, 4).map(item => { const Icon = item.icon; return <button key={item.name} className={view === item.name ? "active" : ""} onClick={() => navigate(item.name)}><Icon /><span>{item.name}</span></button>; })}<button onClick={() => setDrawer(true)}><Menu /><span>More</span></button></nav>
  </div>;
}

function AdminHeader({ view, loading, activities, navigate }: { view: View; loading: boolean; activities: Row[]; navigate: (view: View) => void }) {
  const overview = view === "Overview";
  const [notifications, setNotifications] = useState(false); const [dismissed, setDismissed] = useState<string[]>([]);
  const visibleActivities = activities.filter(activity => !dismissed.includes(text(activity.id)));
  const destination = (activity: Row): View => { const entity = text(activity.entity_type).toLowerCase(); return entity.includes("booking") ? "Bookings" : entity.includes("consultation") ? "Consultations" : entity.includes("order") || entity.includes("payment") ? "Orders" : entity.includes("product") ? "Products" : entity.includes("service") ? "Services" : entity.includes("staff") ? "Staff" : entity.includes("testimonial") || entity.includes("review") ? "Reviews" : "History"; };
  const [identity, setIdentity] = useState({ name: "Admin", email: "" }); useEffect(() => { void supabase?.auth.getUser().then(({ data }) => { const email = data.user?.email || ""; const name = String(data.user?.user_metadata?.full_name || email.split("@")[0] || "Admin"); setIdentity({ name, email }); }); }, []);
  return <header className="adm-top"><span className="adm-mobile-brand"><i /><strong>Gailant<br />Beauty</strong></span><div className="adm-page-intro"><h1>{overview ? `Good ${new Date().getHours() < 12 ? "morning" : new Date().getHours() < 18 ? "afternoon" : "evening"}, ${identity.name}` : view}</h1><p>{overview ? "Your live operating view for today." : `Manage your ${view.toLowerCase()} and salon operations.`}</p></div><div className="adm-header-actions"><button className="adm-icon-button" aria-label="Activity notifications" aria-expanded={notifications} onClick={() => setNotifications(current => !current)}><Bell />{visibleActivities.length > 0 && <i />}</button><div className="adm-profile" aria-label="Admin profile"><span>{identity.name.slice(0, 1).toUpperCase()}</span><span><strong>{identity.name}</strong><small>{identity.email || "Admin"}</small></span></div>{overview && <span className="adm-open-pill">Operations active <i /></span>}<span className="adm-live"><i /> {loading ? "Syncing" : isSupabaseConfigured ? "Live" : "Local"}</span>{notifications && <section className="adm-notification-panel" aria-label="Recent activity"><strong>Recent activity</strong>{visibleActivities.slice(0, 5).map((activity, index) => <article key={text(activity.id, String(index))}><div><b>{text(activity.action).replaceAll(".", " ")}</b><small>{text(activity.entity_type)} · {dateText(activity.created_at)}</small></div><div><button onClick={() => { navigate(destination(activity)); setNotifications(false); }}>View</button><button onClick={() => setDismissed(current => [...current, text(activity.id)])}>Dismiss</button></div></article>)}{!visibleActivities.length && <p>No new operational activity. New bookings, payments, and staff updates will appear here automatically.</p>}</section>}</div></header>;
}

function Overview({ data, navigate }: { data: Record<string, Row[]>; navigate: (view: View) => void }) {
  const today = new Date().toISOString().slice(0, 10);
  const bookings = (data.bookings || []).filter(row => text(row.appointment_date, "").startsWith(today));
  const consultations = (data.consultation_requests || []).filter(row => ["new", "pending"].includes(text(row.status, "").toLowerCase()));
  const lowStock = (data.products || []).filter(row => Number(row.inventory || 0) <= Number(row.low_stock_threshold || 5));
  const posRevenue = (data.orders || []).filter(row => text(row.source, "") === "pos" && text(row.created_at, "").startsWith(today)).reduce((sum, row) => sum + Number(row.total_amount || 0), 0);
  const clients = data.customers || [];
  const stats: Array<[string, string, View, string]> = [["Today’s Bookings", String(bookings.length), "Bookings", bookings.length ? "Review today’s schedule" : "No bookings today"], ["Pending Consultations", String(consultations.length), "Consultations", consultations.length ? "Responses required" : "Inbox is clear"], ["Low Inventory", String(lowStock.length), "Products", lowStock.length ? "Restock attention required" : "Inventory levels are healthy"], ["Clients", String(clients.length), "Clients", "View client records"]];
  const activity = data.activity_log || [];
  return <div className="adm-dashboard"><section className="adm-stats"><button className="adm-revenue-card" onClick={() => navigate("Insights")}><small>Today’s POS Revenue</small><strong>{money(posRevenue)}</strong><span>{posRevenue ? "From completed in-person sales" : "No POS revenue recorded today"}</span></button>{stats.map(([label, value, target, note]) => <button key={label} onClick={() => navigate(target)}><small>{label}</small><strong>{value}</strong><span>{note}</span><b><ChevronRight /></b></button>)}</section><section className="adm-overview-grid"><DashboardCard title="Today’s Schedule" action="View all" onAction={() => navigate("Bookings")}><div className="adm-schedule-list">{bookings.slice(0, 4).map((row, index) => <article key={text(row.id, String(index))}><time>{text(row.appointment_time)}</time><div><strong>{text(row.service_name)}</strong><span>{text(row.name)}</span></div><Status value={text(row.status, "confirmed")} /></article>)}{!bookings.length && <Empty label="No bookings are scheduled for today." />}</div></DashboardCard><DashboardCard title="Recent Activity"><div className="adm-activity-list">{activity.slice(0, 4).map((row, index) => <article key={text(row.id, String(index))}><span className="adm-activity-icon"><ClipboardList /></span><div><strong>{text(row.action).replaceAll(".", " ")}</strong><small>{text(row.entity_type)} {text(row.entity_id, "")}</small></div><time>{dateText(row.created_at)}</time></article>)}{!activity.length && <Empty label="Operational activity will appear after staff actions." />}</div></DashboardCard><DashboardCard title="Low Stock Products" action="View all" onAction={() => navigate("Products")}><div className="adm-stock-list">{lowStock.map((row, index) => <article key={text(row.id, String(index))}><span className="adm-product-dot">{text(row.name).slice(0, 1)}</span><div><strong>{text(row.name)}</strong><small>{Number(row.inventory || 0)} remaining</small></div><b>{Number(row.inventory || 0)}</b></article>)}{!lowStock.length && <Empty label="No products currently require restocking." />}</div></DashboardCard></section></div>;
}

function DashboardCard({ title, action, onAction, children }: { title: string; action?: string; onAction?: () => void; children: React.ReactNode }) { return <section className="adm-dashboard-card"><header><h2>{title}</h2>{action && <button type="button" onClick={onAction}>{action}</button>}</header>{children}</section>; }

function ScheduleView({ rows, refresh, flash }: { rows: Row[]; refresh: () => Promise<void>; flash: (s: string) => void }) {
  const [mode, setMode] = useState<"calendar" | "list">("calendar");
  const [editor, setEditor] = useState<Row | null>(null);
  const [selectedDate, setSelectedDate] = useState(() => new Date()); const [month, setMonth] = useState(() => new Date()); const [service, setService] = useState("all"); const [status, setStatus] = useState("all");
  const selectedKey = selectedDate.toISOString().slice(0, 10); const appointments = rows.filter(row => text(row.appointment_date, "").slice(0, 10) === selectedKey && (service === "all" || text(row.service_name) === service) && (status === "all" || text(row.status).toLowerCase() === status)); const first = new Date(month.getFullYear(), month.getMonth(), 1); const start = new Date(first); start.setDate(1 - first.getDay()); const days = Array.from({ length: 42 }, (_, index) => { const day = new Date(start); day.setDate(start.getDate() + index); return day; }); const services = [...new Set(rows.map(row => text(row.service_name, "")).filter(Boolean))]; const statuses = [...new Set(rows.map(row => text(row.status, "").toLowerCase()).filter(Boolean))]; const label = selectedDate.toLocaleDateString("en-GH", { weekday: "long", day: "numeric", month: "long", year: "numeric" });
  return <section className="adm-calendar-shell"><aside className="adm-calendar-side"><div className="adm-mini-calendar"><header><button aria-label="Previous month" onClick={() => setMonth(current => new Date(current.getFullYear(), current.getMonth() - 1, 1))}>‹</button><strong>{month.toLocaleDateString("en-GH", { month: "long", year: "numeric" })}</strong><button aria-label="Next month" onClick={() => setMonth(current => new Date(current.getFullYear(), current.getMonth() + 1, 1))}>›</button></header><div className="adm-weekdays">{["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map(day => <span key={day}>{day}</span>)}</div><div className="adm-month-days">{days.map(day => { const key = day.toISOString().slice(0, 10); return <button key={key} className={`${key === selectedKey ? "active " : ""}${day.getMonth() !== month.getMonth() ? "muted" : ""}`} onClick={() => setSelectedDate(day)}>{day.getDate()}</button>; })}</div></div><div className="adm-calendar-filters"><p>Filters</p><select aria-label="Filter by service" value={service} onChange={event => setService(event.target.value)}><option value="all">All Services</option>{services.map(value => <option key={value}>{value}</option>)}</select><select aria-label="Filter by status" value={status} onChange={event => setStatus(event.target.value)}><option value="all">All Statuses</option>{statuses.map(value => <option key={value}>{value.replaceAll("_", " ")}</option>)}</select></div><div className="adm-calendar-view"><p>View</p><button className={mode === "calendar" ? "active" : ""} onClick={() => setMode("calendar")}><CalendarDays /> Calendar View</button><button className={mode === "list" ? "active" : ""} onClick={() => setMode("list")}><ClipboardList /> List View</button></div></aside><div className="adm-calendar-main"><div className="adm-calendar-toolbar"><strong>{label}</strong><div><button className={mode === "calendar" ? "active" : ""} onClick={() => setMode("calendar")}>Day</button><button className={mode === "list" ? "active" : ""} onClick={() => setMode("list")}>List</button><button className="adm-primary" onClick={() => setEditor({ appointment_date: selectedKey })}>New Booking</button></div></div>{mode === "calendar" ? <div className="adm-day-agenda">{appointments.map((appointment, index) => <button key={text(appointment.id, String(index))} onClick={() => setEditor(appointment)}><time>{text(appointment.appointment_time)}</time><span><strong>{text(appointment.service_name)}</strong><small>{text(appointment.name)}</small></span><Status value={text(appointment.status, "confirmed")} /></button>)}{!appointments.length && <Empty label="No bookings are scheduled for this date." />}</div> : <Operations view="Bookings" rows={rows} refresh={refresh} flash={flash} />}</div>{editor && <BookingEditor record={editor} onClose={() => setEditor(null)} onSaved={async () => { setEditor(null); flash("Booking saved."); await refresh(); }} />}</section>;
}

function BookingEditor({ record, onClose, onSaved }: { record: Row; onClose: () => void; onSaved: () => Promise<void> }) {
  const [form, setForm] = useState<Row>({ appointment_date: new Date().toISOString().slice(0, 10), appointment_time: "09:00", status: "confirmed", ...record }); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const set = (key: string, value: unknown) => setForm(current => ({ ...current, [key]: value }));
  return <Modal title={record.id ? "Edit booking" : "New booking"} onClose={onClose}><form className="adm-form" onSubmit={async event => { event.preventDefault(); setBusy(true); setError(""); const payload = { name: text(form.name, "Walk-in customer"), phone: text(form.phone, "N/A"), email: text(form.email, "") || null, service_name: text(form.service_name), appointment_date: text(form.appointment_date), appointment_time: text(form.appointment_time), home_service: false, total_amount: Number(form.total_amount || 0), deposit_amount: Number(form.deposit_amount || 0), payment_status: text(form.payment_status, "pending"), status: text(form.status, "confirmed") }; const result = record.id ? await updateRecord("bookings", text(record.id), payload) : await insertRecord("bookings", payload); if (result.error) { setError(result.error); setBusy(false); return } if (result.local && record.id) patchLocalRecord("bookings", text(record.id), payload); await recordActivity(record.id ? "booking.updated" : "booking.created", "booking", text(record.id ?? result.data?.id, ""), { appointment_date: payload.appointment_date }); await onSaved(); }}><div className="adm-form-grid"><label>Client name<input required value={text(form.name, "")} onChange={e => set("name", e.target.value)} /></label><label>Phone<input required value={text(form.phone, "")} onChange={e => set("phone", e.target.value)} /></label><label>Service<input required value={text(form.service_name, "")} onChange={e => set("service_name", e.target.value)} /></label><label>Date<input required type="date" value={text(form.appointment_date, "")} onChange={e => set("appointment_date", e.target.value)} /></label><label>Time<input required type="time" value={text(form.appointment_time, "")} onChange={e => set("appointment_time", e.target.value)} /></label><label>Status<select value={text(form.status, "confirmed")} onChange={e => set("status", e.target.value)}><option value="confirmed">Confirmed</option><option value="pending_payment">Pending payment</option><option value="completed">Completed</option><option value="canceled">Canceled</option></select></label></div>{error && <div className="adm-error">{error}</div>}<div className="adm-modal-actions"><button type="button" className="adm-secondary" onClick={onClose}>Cancel</button><button className="adm-primary" disabled={busy}>{busy ? "Saving…" : "Save booking"}</button></div></form></Modal>;
}

function ClientsView({ rows, orders, bookings, refresh, flash }: { rows: Row[]; orders: Row[]; bookings: Row[]; refresh: () => Promise<void>; flash: (s: string) => void }) {
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState("");
  const [tab, setTab] = useState<"Overview" | "Appointments" | "Purchases" | "Notes">("Overview");
  const [editor, setEditor] = useState<Row | null>(null);
  const [removing, setRemoving] = useState<Row | null>(null);
  const clients = rows.filter(client => JSON.stringify(client).toLowerCase().includes(query.toLowerCase()));
  const selected = rows.find(client => text(client.id) === selectedId) || clients[0];
  const phone = selected ? text(selected.phone, "") : "";
  const clientOrders = orders.filter(row => text(row.phone, "") === phone);
  const clientBookings = bookings.filter(row => text(row.phone, "") === phone);
  const spend = clientOrders.filter(row => text(row.payment_status).toLowerCase() === "paid").reduce((sum, row) => sum + Number(row.total_amount || 0), 0)
    + clientBookings.filter(row => text(row.payment_status).toLowerCase() === "paid").reduce((sum, row) => sum + Number(row.total_amount || 0), 0);
  return (
    <section className={`adm-clients-shell${selectedId ? " detail-open" : ""}`}>
      <aside>
        <div className="adm-clients-sidebar-toolbar">
          <label><Search /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search clients…" /></label>
          <button className="adm-primary" onClick={() => setEditor({})} title="Add new client"><Plus size={16} /> Add Client</button>
        </div>
        <div>{clients.map((client, index) => <button key={text(client.id, String(index))} className={selected && text(client.id) === text(selected.id) ? "active" : ""} onClick={() => setSelectedId(text(client.id))}><span>{text(client.full_name).slice(0, 1)}</span><span><strong>{text(client.full_name)}</strong><small>{text(client.phone)}</small></span><ChevronRight /></button>)}
          {!clients.length && <Empty label={rows.length ? "No clients match this search." : "Client records appear after a booking, order, or POS sale."} action="Add Client" onAction={() => setEditor({})} />}
        </div>
      </aside>
      {selected && (
        <main>
          <button type="button" className="adm-client-mobile-back" onClick={() => setSelectedId("")}><ArrowLeft /> Back to client list</button>
          <header className="adm-client-profile">
            <span>{text(selected.full_name).slice(0, 1)}</span>
            <div><h2>{text(selected.full_name)}</h2><p>{text(selected.phone)}</p><p>{text(selected.email)}</p></div>
            <div className="adm-client-actions">
              <button className="adm-secondary" onClick={() => setEditor(selected)} title="Edit client"><Pencil size={15} /> Edit</button>
              <button className="adm-secondary danger" onClick={() => setRemoving(selected)} title="Delete client"><Trash2 size={15} /></button>
            </div>
          </header>
          <section className="adm-client-stats">
            <div><small>Total Paid</small><strong>{money(spend)}</strong></div>
            <div><small>Appointments</small><strong>{clientBookings.length}</strong></div>
            <div><small>Customer Since</small><strong>{selected.created_at ? new Date(text(selected.created_at)).toLocaleDateString("en-GH", { month: "short", year: "numeric" }) : "—"}</strong></div>
          </section>
          <nav className="adm-client-tabs">{(["Overview", "Appointments", "Purchases", "Notes"] as const).map(value => <button key={value} className={tab === value ? "active" : ""} onClick={() => setTab(value)}>{value}</button>)}</nav>
          {tab === "Overview" && <div className="adm-client-detail-grid"><DashboardCard title="Contact information"><dl><div><dt>Phone</dt><dd>{text(selected.phone)}</dd></div><div><dt>Email</dt><dd>{text(selected.email)}</dd></div><div><dt>Address</dt><dd>{text(selected.address)}</dd></div></dl></DashboardCard><DashboardCard title="Relationship summary"><p>{clientBookings.length} appointments and {clientOrders.length} product orders are linked by this client&apos;s phone number.</p></DashboardCard></div>}
          {tab === "Appointments" && <div className="adm-client-records">{clientBookings.map((row, index) => <article key={text(row.id, String(index))}><div><strong>{text(row.service_name)}</strong><small>{text(row.appointment_date)} at {text(row.appointment_time)}</small></div><Status value={text(row.status)} /></article>)}{!clientBookings.length && <Empty label="No appointments are linked to this client." />}</div>}
          {tab === "Purchases" && <div className="adm-client-records">{clientOrders.map((row, index) => <article key={text(row.id, String(index))}><div><strong>{text(row.reference)}</strong><small>{dateText(row.created_at)}</small></div><b>{money(row.total_amount)}</b></article>)}{!clientOrders.length && <Empty label="No product purchases are linked to this client." />}</div>}
          {tab === "Notes" && <DashboardCard title="Client notes"><p>{text(selected.notes, "No client notes have been recorded.")}</p></DashboardCard>}
        </main>
      )}
      {editor && <RecordEditor view="Clients" record={editor} onClose={() => setEditor(null)} onSaved={async () => { setEditor(null); flash(editor.id ? "Client updated." : "Client added."); await refresh(); }} />}
      {removing && <ConfirmModal title="Delete client?" body={`This permanently removes ${text(removing.full_name, "this client")} and cannot be undone. Their linked bookings and orders are not affected.`} onCancel={() => setRemoving(null)} onConfirm={async () => { const result = await deleteRecord("customers", text(removing.id)); if (!result.error) { if (selected && text(selected.id) === text(removing.id)) setSelectedId(""); flash("Client deleted."); await refresh(); } setRemoving(null); }} />}
    </section>
  );
}

function Operations({ view, rows, refresh, flash }: { view: View; rows: Row[]; refresh: () => Promise<void>; flash: (s: string) => void }) {
  const [query, setQuery] = useState(""); const [filter, setFilter] = useState("all"); const [open, setOpen] = useState(""); const [selected, setSelected] = useState<string[]>([]);
  const statuses = view === "Orders" ? ["all", "pending_payment", "paid", "preparing", "dispatched", "delivered"] : view === "Bookings" ? ["all", "pending_payment", "confirmed", "in_service", "completed", "canceled"] : ["all", "new", "contacted", "converted", "closed"];
  const filtered = rows.filter(row => (filter === "all" || text(row.status, "").toLowerCase() === filter) && JSON.stringify(row).toLowerCase().includes(query.toLowerCase()));
  const actionLabel = (row: Row) => { const next = statuses[Math.min(statuses.indexOf(text(row.status, statuses[1])) + 1, statuses.length - 1)]; const labels: Record<string, string> = { paid: "Confirm payment", preparing: "Begin preparation", dispatched: "Mark dispatched", delivered: "Mark delivered", confirmed: "Confirm booking", in_service: "Begin service", completed: "Complete service", contacted: "Mark contacted", converted: "Convert to booking", closed: "Close request" }; return labels[next] || "Status complete"; };
  const advance = async (row: Row) => { const sequence = statuses.slice(1); const current = sequence.indexOf(text(row.status, sequence[0])); const status = sequence[Math.min(current + 1, sequence.length - 1)]; const result = await updateRecord(viewTable[view]!, text(row.id), { status }); if (result.error) { flash(result.error); return; } if (!isSupabaseConfigured) patchLocalRecord(viewTable[view]!, text(row.id), { status }); await recordActivity(`${viewTable[view]}.status_updated`, viewTable[view]!, text(row.id), { status }); flash(`Status updated to ${status.replaceAll("_", " ")}.`); await refresh(); };
  const bulkAdvance = async () => { for (const id of selected) { const row = rows.find(item => text(item.id) === id); if (row) await advance(row); } setSelected([]); };
  return <section className="adm-panel"><div className="adm-toolbar"><label><Search /><input placeholder={`Search ${view.toLowerCase()}…`} value={query} onChange={e => setQuery(e.target.value)} /></label><button className="adm-secondary" onClick={() => exportCsv(view, filtered)}><Download /> Export CSV</button></div><div className="adm-pills">{statuses.map(status => <button key={status} className={filter === status ? "active" : ""} onClick={() => setFilter(status)}>{status.replaceAll("_", " ")}</button>)}</div>{selected.length > 0 && <div className="adm-bulk"><span>{selected.length} selected</span><button onClick={bulkAdvance}>Move selected to next stage</button><button onClick={() => setSelected([])}>Clear</button></div>}<div className="adm-operation-list">{filtered.map(row => { const id = text(row.id, text(row.reference)); const expanded = open === id; const activeIndex = Math.max(0, statuses.slice(1).indexOf(text(row.status, statuses[1]))); const finalStage = activeIndex >= statuses.length - 2; return <article key={id} className={expanded ? "open" : ""}><div className="adm-operation-head"><input aria-label="Select record" type="checkbox" checked={selected.includes(id)} onChange={e => setSelected(current => e.target.checked ? [...current, id] : current.filter(item => item !== id))} /><button onClick={() => setOpen(expanded ? "" : id)} aria-expanded={expanded}><span><strong>{text(row.name, "Walk-in customer")}</strong><small>{text(row.reference, id)}</small></span><span>{text(row.service_name, view === "Orders" ? `${Array.isArray(row.items) ? row.items.length : 0} items` : "General inquiry")}</span><Status value={text(row.status, "new")} /><ChevronDown className={expanded ? "rotated" : ""} /></button></div>{expanded && <div className="adm-operation-body"><div className="adm-stepper">{statuses.slice(1).map((status, index) => <span key={status} className={index <= activeIndex ? "active" : ""}><i>{index + 1}</i><small>{status.replaceAll("_", " ")}</small></span>)}</div><dl><div><dt>Phone</dt><dd>{text(row.phone)}</dd></div><div><dt>Email</dt><dd>{text(row.email)}</dd></div><div><dt>Created</dt><dd>{dateText(row.created_at)}</dd></div><div><dt>Total</dt><dd>{money(row.total_amount)}</dd></div></dl><div className="adm-card-actions">{text(row.phone, "") && <a className="adm-secondary" href={`tel:${text(row.phone, "")}`}>Contact client</a>}<button className="adm-primary" disabled={finalStage} onClick={() => advance(row)}>{finalStage ? "Workflow complete" : actionLabel(row)}</button></div></div>}</article>; })}{!filtered.length && <Empty label={`No ${view.toLowerCase()} match this view.`} detail={`New ${view.toLowerCase()} will appear automatically when customers complete the connected storefront workflow.`} />}</div></section>;
}

const singularView = (view: View) => view === "Staff" ? "Staff" : view.slice(0, -1);

function DataView({ view, rows, refresh, flash }: { view: View; rows: Row[]; refresh: () => Promise<void>; flash: (s: string) => void }) {
  const [query, setQuery] = useState(""); const [status, setStatus] = useState("all"); const [editor, setEditor] = useState<Row | null>(null); const [remove, setRemove] = useState<Row | null>(null); const [page, setPage] = useState(1);
  const filtered = rows.filter(row => JSON.stringify(row).toLowerCase().includes(query.toLowerCase()) && (status === "all" || String(row.active ?? row.published ?? true) === status));
  const pageSize = 25; const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize)); const safePage = Math.min(page, pageCount); const paged = filtered.slice((safePage - 1) * pageSize, safePage * pageSize);
  return <section className="adm-panel"><div className="adm-toolbar"><label><Search /><input value={query} onChange={e => setQuery(e.target.value)} placeholder={`Search ${view.toLowerCase()}…`} /></label><select aria-label="Status filter" value={status} onChange={e => setStatus(e.target.value)}><option value="all">All statuses</option><option value="true">Active / published</option><option value="false">Inactive / draft</option></select><button className="adm-secondary" onClick={() => exportCsv(view, filtered)}><Download /> Export CSV</button><button className="adm-primary" onClick={() => setEditor({})}><Plus /> Add {singularView(view)}</button></div><div className="adm-table-wrap"><table><thead><tr><th>Name</th><th>Category / contact</th><th>Price / detail</th><th>Status</th><th /></tr></thead><tbody>{paged.map((row, index) => { const image = text(row.primary_image_url ?? row.avatar_url ?? row.customer_image_url, ""); return <tr key={text(row.id, String(index))}><td><span className="adm-record-name">{image && <img src={image} alt="" loading="lazy" />}<span><strong>{text(row.name ?? row.full_name ?? row.customer_name, "Untitled")}</strong><small>{text(row.slug ?? row.email ?? row.service_name, "")}</small></span></span></td><td>{text(row.category ?? row.phone ?? row.role)}</td><td>{row.price != null ? money(row.price) : text(row.inventory ?? row.rating ?? row.email)}</td><td><Status value={(row.active ?? row.published ?? true) ? "active" : "inactive"} /></td><td><button onClick={() => setEditor(row)}>Edit</button><button className="danger" onClick={() => setRemove(row)}><Trash2 /></button></td></tr>; })}</tbody></table>{!filtered.length && <Empty label={`No ${view.toLowerCase()} found.`} />}</div>{filtered.length > pageSize && <nav className="adm-pagination" aria-label={`${view} pagination`}><button disabled={page === 1} onClick={() => setPage(current => Math.max(1, current - 1))}>Previous</button><span>Page {page} of {pageCount}</span><button disabled={page === pageCount} onClick={() => setPage(current => Math.min(pageCount, current + 1))}>Next</button></nav>}{editor && <RecordEditor view={view} record={editor} onClose={() => setEditor(null)} onSaved={async () => { setEditor(null); flash(`${singularView(view)} saved.`); await refresh(); }} />}{remove && <ConfirmModal title={`Delete ${singularView(view)}?`} body="This removes the record permanently. This action cannot be undone." onCancel={() => setRemove(null)} onConfirm={async () => { const table = viewTable[view]!; const id = text(remove.id); const ids = Array.isArray(remove.cloudinary_public_ids) ? remove.cloudinary_public_ids.map(String) : []; const result = await deleteRecord(table, id); if (result.local) deleteLocalRecords(table, [id]); if (ids.length) await cleanupImages(ids); setRemove(null); flash("Record deleted."); await refresh(); }} />}</section>;
}

function RecordEditor({ view, record, onClose, onSaved }: { view: View; record: Row; onClose: () => void; onSaved: () => Promise<void> }) {
  const [form, setForm] = useState<Row>(record); const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const [uploadProgress, setUploadProgress] = useState(0); const [retryFile, setRetryFile] = useState<File | null>(null); const [orphaned, setOrphaned] = useState<string[]>([]);
  const imageViews = ["Services", "Products", "Staff"].includes(view); const nameKey = view === "Reviews" ? "customer_name" : view === "Staff" || view === "Clients" ? "full_name" : "name";
  const set = (key: string, value: unknown) => setForm(current => ({ ...current, [key]: value }));
  const currentImage = text(form.primary_image_url ?? form.avatar_url, ""); const upload = async (file: File) => { setBusy(true); setError(""); setRetryFile(file); setUploadProgress(1); try { const image = await uploadImage(file, setUploadProgress); const previous = Array.isArray(form.cloudinary_public_ids) ? form.cloudinary_public_ids.map(String) : []; setOrphaned(ids => [...ids, ...previous]); set("primary_image_url", image.url); set("avatar_url", image.url); set("cloudinary_public_ids", [image.publicId]); setRetryFile(null); } catch (cause) { setError(cause instanceof Error ? cause.message : "Upload failed."); } finally { setBusy(false); } };
  return <Modal title={record.id ? `Edit ${singularView(view)}` : `Add ${singularView(view)}`} onClose={onClose}><form className="adm-form" onSubmit={async event => { event.preventDefault(); setBusy(true); setError(""); const table = viewTable[view]!; const payload = { ...form, ...(view === "Services" || view === "Products" ? { slug: text(form.slug, slug(text(form[nameKey]))) } : {}) }; const result = record.id ? await updateRecord(table, text(record.id), payload) : await insertRecord(table, payload); if (result.error) { setError(result.error); setBusy(false); return; } if (result.local) { if (record.id) patchLocalRecord(table, text(record.id), payload); else if (["services", "products"].includes(table)) { const catalog = loadCatalog({ services: SERVICES, products: PRODUCTS, testimonials: [] }); saveCatalog({ ...catalog, [table]: [...(catalog[table as "services" | "products"] as unknown as Row[]), result.data] } as never); } } if (orphaned.length) await cleanupImages(orphaned); await onSaved(); }}><div className="adm-form-grid"><label>Name<input required value={text(form[nameKey], "")} onChange={e => set(nameKey, e.target.value)} /></label>{view !== "Clients" && <label>{view === "Staff" ? "Role" : "Category"}<input value={text(form[view === "Staff" ? "role" : "category"], "")} onChange={e => set(view === "Staff" ? "role" : "category", e.target.value)} /></label>}{["Services", "Products"].includes(view) && <label>Price (GHS)<input type="number" min="0" step="0.01" value={Number(form.price || 0)} onChange={e => set("price", Number(e.target.value))} /></label>}{view === "Products" && <label>Inventory<input type="number" min="0" value={Number(form.inventory || 0)} onChange={e => set("inventory", Number(e.target.value))} /></label>}{["Clients", "Staff"].includes(view) && <><label>Phone<input value={text(form.phone, "")} onChange={e => set("phone", e.target.value)} /></label><label>Email<input type="email" value={text(form.email, "")} onChange={e => set("email", e.target.value)} /></label></>}{view === "Reviews" && <><label>Service<input value={text(form.service_name, "")} onChange={e => set("service_name", e.target.value)} /></label><label>Rating<input type="number" min="1" max="5" value={Number(form.rating || 5)} onChange={e => set("rating", Number(e.target.value))} /></label></>}</div>{view === "Reviews" ? <label>Review<textarea required value={text(form.quote, "")} onChange={e => set("quote", e.target.value)} /></label> : view === "Clients" ? <label>Notes<textarea placeholder="Allergies, preferences, or anything worth remembering…" value={text(form.notes, "")} onChange={e => set("notes", e.target.value)} /></label> : !["Staff"].includes(view) && <label>Description<textarea value={text(form.description, "")} onChange={e => set("description", e.target.value)} /></label>}{imageViews && <section className="adm-media-editor"><div className="adm-media-preview">{currentImage ? <img src={currentImage} alt={`${text(form[nameKey], singularView(view))} preview`} /> : <ImagePlus aria-hidden="true" />}</div><div><label className="adm-upload"><ImagePlus /> {currentImage ? "Replace image" : "Upload image"}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={event => { const file = event.target.files?.[0]; if (file) void upload(file); }} /></label>{uploadProgress > 0 && uploadProgress < 100 && <div className="adm-upload-progress" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={uploadProgress}><span style={{ width: `${uploadProgress}%` }} /></div>}{retryFile && error && <button type="button" className="adm-secondary" onClick={() => void upload(retryFile)}>Retry upload</button>}{currentImage && <button type="button" className="adm-secondary" onClick={() => { const ids = Array.isArray(form.cloudinary_public_ids) ? form.cloudinary_public_ids.map(String) : []; setOrphaned(current => [...current, ...ids]); set("primary_image_url", ""); set("avatar_url", ""); set("cloudinary_public_ids", []); }}>Remove image</button>}{!currentImage && text(record.primary_image_url ?? record.avatar_url, "") && <button type="button" className="adm-secondary" onClick={() => { set("primary_image_url", record.primary_image_url); set("avatar_url", record.avatar_url); set("cloudinary_public_ids", record.cloudinary_public_ids); setOrphaned([]); }}>Restore preview</button>}<small>JPEG, PNG, or WebP · at least 600 × 600 · up to 10 MB</small></div></section>}{view !== "Clients" && <label className="adm-check"><input type="checkbox" checked={Boolean(form.active ?? form.published ?? true)} onChange={e => set(view === "Reviews" ? "published" : "active", e.target.checked)} /> Active / published</label>}{error && <div className="adm-error">{error}</div>}<div className="adm-modal-actions"><button type="button" className="adm-secondary" onClick={onClose}>Cancel</button><button className="adm-primary" disabled={busy}>{busy ? "Saving…" : "Save record"}</button></div></form></Modal>;
}

function PointOfSale({ products, services, refresh, flash }: { products: Row[]; services: Row[]; refresh: () => Promise<void>; flash: (s: string) => void }) {
  const [mode, setMode] = useState<"all" | "product" | "service">("all"); const [query, setQuery] = useState(""); const [cart, setCart] = useState<CartLine[]>([]); const [checkout, setCheckout] = useState(false); const [receipt, setReceipt] = useState<Receipt | null>(null);
  const catalog = useMemo<Array<Row & { kind: "product" | "service" }>>(() => [...products.map(row => ({ ...row, kind: "product" as const } as Row & { kind: "product" })), ...services.map(row => ({ ...row, kind: "service" as const } as Row & { kind: "service" }))].filter(row => (mode === "all" || row.kind === mode) && text(row.name).toLowerCase().includes(query.toLowerCase()) && (row.kind === "service" || Number(row.inventory || 0) > 0)), [products, services, mode, query]);
  const total = cart.reduce((sum, line) => sum + line.price * line.quantity, 0);
  const add = (row: Row & { kind: "product" | "service" }) => setCart(current => { const id = text(row.id); const key = `${row.kind}-${id}`; const existing = current.find(line => line.key === key); if (existing) return current.map(line => line.key === key ? { ...line, quantity: Math.min(line.quantity + 1, line.inventory ?? 99) } : line); return [...current, { key, id, kind: row.kind, name: text(row.name), price: Number(row.price || 0), quantity: 1, inventory: row.kind === "product" ? Number(row.inventory || 0) : undefined }]; });
  const quantity = (key: string, delta: number) => setCart(current => current.map(line => line.key === key ? { ...line, quantity: Math.max(0, Math.min(line.quantity + delta, line.inventory ?? 99)) } : line).filter(line => line.quantity > 0));
  return <div className="adm-pos"><section className="adm-pos-catalog adm-panel"><div className="adm-section-head"><h2>Add Products</h2></div><div className="adm-toolbar"><label><Search /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search products…" /></label></div><div className="adm-pills"><button className={mode === "all" ? "active" : ""} onClick={() => setMode("all")}>All</button><button className={mode === "service" ? "active" : ""} onClick={() => setMode("service")}>Services</button><button className={mode === "product" ? "active" : ""} onClick={() => setMode("product")}>Products</button></div><div className="adm-pos-grid">{catalog.map((row, index) => <button key={`${row.kind}-${text(row.id, String(index))}`} onClick={() => add(row)}><span className="adm-pos-thumb">{row.kind === "service" ? <BookOpen /> : <ShoppingBag />}</span><span><small>{row.kind}{row.kind === "product" ? ` · ${Number(row.inventory || 0)} in stock` : ""}</small><strong>{text(row.name)}</strong><b>{money(row.price)}</b></span><Plus /></button>)}</div></section><aside className="adm-pos-cart adm-panel"><div className="adm-section-head"><h2>Sale Summary</h2><span>{cart.reduce((sum, line) => sum + line.quantity, 0)} items</span></div><div className="adm-cart-lines">{cart.map(line => <article key={line.key}><div><strong>{line.name}</strong><small>{line.kind}</small></div><div className="adm-qty"><button onClick={() => quantity(line.key, -1)} aria-label="Decrease"><Minus /></button><span>{line.quantity}</span><button onClick={() => quantity(line.key, 1)} aria-label="Increase"><Plus /></button></div><b>{money(line.price * line.quantity)}</b></article>)}{!cart.length && <Empty label="Select services or products to begin a sale." />}</div><div className="adm-sale-totals"><div><span>Subtotal</span><b>{money(total)}</b></div><div><span>Discount</span><b>- {money(0)}</b></div></div><div className="adm-cart-total"><span>Total</span><strong>{money(total)}</strong></div><button className="adm-primary adm-checkout" disabled={!cart.length} onClick={() => setCheckout(true)}>Process Payment</button></aside><aside className="adm-pos-payment adm-panel"><div className="adm-section-head"><h2>Customer</h2></div><button className="adm-customer-select"><Users /> Walk-in Customer <ChevronDown /></button><button className="adm-add-customer"><Plus /> Add Customer</button><div className="adm-section-head"><h2>Payment Method</h2></div>{["Cash", "Card", "Mobile Money", "Bank Transfer"].map((method, index) => <button key={method} className={index === 0 ? "active" : ""} onClick={() => cart.length && setCheckout(true)}><WalletCards /> {method}</button>)}</aside>{checkout && <CheckoutModal cart={cart} total={total} onClose={() => setCheckout(false)} onComplete={async completeReceipt => { setCheckout(false); setReceipt(completeReceipt); setCart([]); flash("Sale completed and inventory updated."); await refresh(); }} />}{receipt && <ReceiptModal receipt={receipt} onClose={() => setReceipt(null)} />}</div>;
}

function CheckoutModal({ cart, total, onClose, onComplete }: { cart: CartLine[]; total: number; onClose: () => void; onComplete: (receipt: Receipt) => Promise<void> }) {
  const [name, setName] = useState(""); const [phone, setPhone] = useState(""); const [email, setEmail] = useState(""); const [payment, setPayment] = useState<"cash" | "paystack">("cash"); const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const finalize = async (paymentReference?: string) => {
    const customerPhone = phone.trim();
    if (customerPhone.length < 7) { setError("Enter a valid phone number to complete the sale."); return; }
    setBusy(true); setError(""); const customerName = name.trim() || "Walk-in customer";
    try {
      const token = payment === "cash" ? (await supabase?.auth.getSession())?.data.session?.access_token : undefined;
      const response = await fetch("/api/payments/complete", { method: "POST", headers: { "content-type": "application/json", ...(token ? { authorization: `Bearer ${token}` } : {}) }, body: JSON.stringify({ kind: "pos", paymentMethod: payment, paymentReference, amount: total, customer: { name: customerName, phone: customerPhone, email: email.trim() || undefined }, items: cart.map(({ id, name, price, quantity, kind }) => ({ id, name, price, quantity, kind })) }) });
      const result = await response.json() as { error?: string; receipt?: { reference?: string; paidAt?: string } };
      if (!response.ok) throw new Error(result.error || "The sale could not be verified.");
      await onComplete({ reference: result.receipt?.reference || paymentReference || "POS", items: cart, total, date: result.receipt?.paidAt || new Date().toISOString(), payment: payment === "cash" ? "Cash" : "Paystack", customer: customerName });
    } catch (cause) { setError(cause instanceof Error ? cause.message : "The sale could not be completed."); setBusy(false); }
  };
  const submit = async (event: React.FormEvent) => { event.preventDefault(); if (payment === "cash") { await finalize(); return; } if (!email.trim()) { setError("An email address is required for Paystack checkout."); return; } setBusy(true); try { await openPaystackPayment({ email: email.trim(), amountGHS: total, metadata: { source: "admin_pos", customer_name: name || "Walk-in customer" }, onSuccess: reference => { void finalize(reference); }, onClose: () => setBusy(false) }); } catch (cause) { setError(cause instanceof Error ? cause.message : "Paystack could not start."); setBusy(false); } };
  return <Modal title="Complete sale" onClose={onClose}><form className="adm-form" onSubmit={submit}><p className="adm-form-intro">A phone number is required for the receipt and private order tracking. Name and email remain optional for cash sales.</p><div className="adm-form-grid"><label>Customer name <span>Optional</span><input value={name} onChange={e => setName(e.target.value)} /></label><label>Phone <span>Required</span><input required minLength={7} inputMode="tel" value={phone} onChange={e => setPhone(e.target.value)} /></label><label>Email <span>{payment === "paystack" ? "Required" : "Optional"}</span><input type="email" value={email} onChange={e => setEmail(e.target.value)} /></label></div><fieldset className="adm-pay-method"><legend>Payment method</legend><button type="button" className={payment === "cash" ? "active" : ""} onClick={() => setPayment("cash")}><strong>Cash</strong><span>Mark paid immediately</span></button><button type="button" className={payment === "paystack" ? "active" : ""} onClick={() => setPayment("paystack")}><strong>Paystack</strong><span>Card or mobile money</span></button></fieldset><div className="adm-checkout-summary"><span>Amount due</span><strong>{money(total)}</strong></div>{error && <div className="adm-error">{error}</div>}<div className="adm-modal-actions"><button type="button" className="adm-secondary" onClick={onClose}>Cancel</button><button className="adm-primary" disabled={busy}>{busy ? "Processing…" : payment === "cash" ? "Complete cash sale" : "Pay with Paystack"}</button></div></form></Modal>;
}

function ReceiptModal({ receipt, onClose }: { receipt: Receipt; onClose: () => void }) {
  const receiptText = `GAILANT BEAUTY\nBeauty, Crowned.\n\nReceipt: ${receipt.reference}\nDate: ${new Date(receipt.date).toLocaleString("en-GH")}\nCustomer: ${receipt.customer}\nPayment: ${receipt.payment}\n\n${receipt.items.map(line => `${line.quantity} × ${line.name} — ${money(line.price * line.quantity)}`).join("\n")}\n\nTOTAL: ${money(receipt.total)}\n\nThank you for choosing Gailant Beauty.`;
  const download = () => { const url = URL.createObjectURL(new Blob([receiptText], { type: "text/plain" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${receipt.reference}.txt`; anchor.click(); URL.revokeObjectURL(url); };
  return <Modal title="Sale complete" onClose={onClose}><div className="adm-receipt"><div className="adm-receipt-brand"><strong>Gailant Beauty</strong><span>Beauty, Crowned.</span></div><dl><div><dt>Receipt</dt><dd>{receipt.reference}</dd></div><div><dt>Date</dt><dd>{new Date(receipt.date).toLocaleString("en-GH")}</dd></div><div><dt>Customer</dt><dd>{receipt.customer}</dd></div><div><dt>Payment</dt><dd>{receipt.payment}</dd></div></dl>{receipt.items.map(line => <div className="adm-receipt-line" key={line.key}><span>{line.quantity} × {line.name}</span><b>{money(line.price * line.quantity)}</b></div>)}<div className="adm-receipt-total"><span>Total</span><strong>{money(receipt.total)}</strong></div><div className="adm-modal-actions"><button className="adm-secondary" onClick={() => window.print()}>Print</button><button className="adm-primary" onClick={download}><Download /> Download receipt</button></div></div></Modal>;
}

function HistoryView({ data }: { data: Record<string, Row[]> }) { const rows = [...(data.orders || []), ...(data.bookings || []), ...(data.consultation_requests || [])].filter(row => ["completed", "delivered", "closed", "canceled"].includes(text(row.status, "").toLowerCase())).sort((a, b) => text(b.updated_at ?? b.created_at).localeCompare(text(a.updated_at ?? a.created_at))); return <section className="adm-panel"><div className="adm-section-head"><div><p className="adm-kicker">ARCHIVE</p><h2>Completed activity</h2></div><button className="adm-secondary" onClick={() => exportCsv("History", rows)}><Download /> Export CSV</button></div><div className="adm-history">{rows.map((row, index) => <article key={text(row.id, String(index))}><Status value={text(row.status)} /><div><strong>{text(row.name, "Client")}</strong><span>{text(row.reference)}</span></div><time>{dateText(row.updated_at ?? row.created_at)}</time></article>)}{!rows.length && <Empty label="Completed activity will appear here." />}</div></section>; }

function Insights({ data }: { data: Record<string, Row[]> }) { const orders = data.orders || []; const bookings = data.bookings || []; const clients = data.customers || []; const paidOrders = orders.filter(row => text(row.payment_status).toLowerCase() === "paid"); const paidBookings = bookings.filter(row => text(row.payment_status).toLowerCase() === "paid"); const revenue = [...paidOrders, ...paidBookings].reduce((sum, row) => sum + Number(row.total_amount || 0), 0); const serviceRevenue = new Map<string, number>(); paidBookings.forEach(row => { const name = text(row.service_name, "Unspecified service"); serviceRevenue.set(name, (serviceRevenue.get(name) || 0) + Number(row.total_amount || 0)); }); const topServices = [...serviceRevenue.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6); const paymentMethods = new Map<string, number>();[...paidOrders, ...paidBookings].forEach(row => { const method = text(row.payment_provider, "Unspecified"); paymentMethods.set(method, (paymentMethods.get(method) || 0) + Number(row.total_amount || 0)); }); return <div className="adm-reports"><section className="adm-report-kpis">{[["Paid Revenue", money(revenue)], ["Bookings", String(bookings.length)], ["Clients", String(clients.length)], ["Orders", String(orders.length)]].map(([label, value]) => <article key={label}><small>{label}</small><strong>{value}</strong></article>)}</section><section className="adm-report-grid"><DashboardCard title="Revenue by Service"><div className="adm-insight-list">{topServices.map(([name, value]) => <article key={name}><span>{name}</span><strong>{money(value)}</strong></article>)}{!topServices.length && <Empty label="Paid service revenue will appear after completed payments." />}</div></DashboardCard><DashboardCard title="Payment Methods"><div className="adm-insight-list">{[...paymentMethods.entries()].sort((a, b) => b[1] - a[1]).map(([method, value]) => <article key={method}><span>{method.replaceAll("_", " ")}</span><strong>{money(value)}</strong></article>)}{!paymentMethods.size && <Empty label="Payment method totals will appear after completed payments." />}</div></DashboardCard></section></div>; }

function SettingsView({ rows, refresh, flash }: { rows: Row[]; refresh: () => Promise<void>; flash: (s: string) => void }) { const [form, setForm] = useState<Row>(() => rows[0] || { id: "default", business_name: "Gailant Beauty" }); const set = (key: string, value: string) => setForm(current => ({ ...current, [key]: value })); return <section className="adm-panel"><div className="adm-section-head"><div><p className="adm-kicker">STUDIO</p><h2>Business settings</h2></div></div><form className="adm-form adm-settings" onSubmit={async event => { event.preventDefault(); const result = await upsertRecord("business_settings", form, "id"); if (result.local) patchLocalRecord("business_settings", "default", form); flash(result.error || "Settings saved."); await refresh(); }}><div className="adm-form-grid">{[["business_name", "Business name"], ["tagline", "Tagline"], ["location", "Location"], ["primary_phone", "Primary phone"], ["secondary_phone", "Secondary phone"], ["opening_hours", "Opening hours"]].map(([key, label]) => <label key={key}>{label}<input value={text(form[key], "")} onChange={e => set(key, e.target.value)} /></label>)}</div><button className="adm-primary">Save settings</button></form></section>; }

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) { const dialog = useRef<HTMLElement>(null); useEffect(() => { const previous = document.activeElement as HTMLElement | null; const root = dialog.current; const controls = () => Array.from(root?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]') || []); controls()[0]?.focus(); const keydown = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); if (event.key !== "Tab") return; const items = controls(); if (!items.length) return; const first = items[0], last = items[items.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } }; document.addEventListener("keydown", keydown); return () => { document.removeEventListener("keydown", keydown); previous?.focus(); }; }, [onClose]); return <div className="adm-modal-backdrop" role="presentation" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><section ref={dialog} className="adm-modal" role="dialog" aria-modal="true" aria-label={title}><header><div><p className="adm-kicker">GAILANT ADMIN</p><h2>{title}</h2></div><button onClick={onClose} aria-label="Close"><X /></button></header>{children}</section></div>; }
function ConfirmModal({ title, body, onCancel, onConfirm }: { title: string; body: string; onCancel: () => void; onConfirm: () => Promise<void> }) { const [busy, setBusy] = useState(false); return <Modal title={title} onClose={onCancel}><p>{body}</p><div className="adm-modal-actions"><button className="adm-secondary" onClick={onCancel}>Cancel</button><button className="adm-danger" disabled={busy} onClick={async () => { setBusy(true); await onConfirm(); }}>{busy ? "Deleting…" : "Delete permanently"}</button></div></Modal>; }
function Status({ value }: { value: string }) { return <span className={`adm-status ${slug(value)}`}>{value.replaceAll("_", " ")}</span>; }
function Empty({ label, detail, action, onAction }: { label: string; detail?: string; action?: string; onAction?: () => void }) { return <div className="adm-empty"><Lightbulb /><strong>{label}</strong><p>{detail || "Records created through connected workflows will appear here automatically."}</p>{action && onAction && <button className="adm-secondary" onClick={onAction}>{action}</button>}</div>; }
function exportCsv(name: string, rows: Row[]) { const keys = [...new Set(rows.flatMap(row => Object.keys(row)))]; const escape = (value: unknown) => `"${String(typeof value === "object" ? JSON.stringify(value) : value ?? "").replaceAll('"', '""')}"`; const csv = [keys.join(","), ...rows.map(row => keys.map(key => escape(row[key])).join(","))].join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${slug(name)}-${new Date().toISOString().slice(0, 10)}.csv`; anchor.click(); URL.revokeObjectURL(url); }
